global $wpdb;
$report = array();
foreach ( $translations as $slug => $html ) {
    $user = get_user_by( 'slug', $slug );
    if ( ! $user instanceof WP_User ) {
        $report[] = array( 'slug' => $slug, 'status' => 'user-not-found' );
        continue;
    }
    update_user_meta( $user->ID, '_mdo_en_store_description', $html );
    $saved = (string) get_user_meta( $user->ID, '_mdo_en_store_description', true );
    $published = (int) $wpdb->get_var(
        $wpdb->prepare(
            "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type='product' AND post_status='publish' AND post_author=%d",
            $user->ID
        )
    );
    $report[] = array(
        'slug' => $slug,
        'user_id' => $user->ID,
        'published_products' => $published,
        'english_chars' => mb_strlen( trim( wp_strip_all_tags( $saved ) ) ),
        'saved' => hash_equals( hash( 'sha256', $html ), hash( 'sha256', $saved ) ),
    );
}

echo wp_json_encode( $report, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES ), "\n";
